{"command":"python3 - <<'PY'
import zlib, struct, subprocess, re
def png(path,w,h,pixels,ct=2):
    raw=b""
    for y in range(h):
        raw+=b"\x00"
        for x in range(w):
            raw+=bytes(pixels[y][x])
    def chunk(t,d):
        return struct.pack(">I",len(d))+t+d+struct.pack(">I", zlib.crc32(t+d)&0xffffffff)
    ihdr=struct.pack(">IIBBBBB",w,h,8,ct,0,0,0)
    open(path,"wb").write(b"\x89PNG\r\n\x1a\n"+chunk(b"IHDR",ihdr)+chunk(b"IDAT",zlib.compress(raw))+chunk(b"IEND",b""))
def render(path,tc,tr,extra=[]):
    p=subprocess.run(["./executable","-tc",str(tc),"-tr",str(tr)]+extra+[path],capture_output=True)
    out=p.stdout.decode()
    rows=[]
    for line in out.strip().split("\n"):
        if not line: continue
        cells=re.findall(r"48;2;(\d+);(\d+);(\d+)m\x1b\[38;2;(\d+);(\d+);(\d+)m(.)",line)
        # flatten bg,fg per col
        flat=[]
        chars=[]
        for c in cells:
            flat.append(int(c[0])); flat.append(int(c[3])); chars.append(c[6])
        rows.append((flat,chars))
    return rows

# vertical gradient value = y*10
for H in [4,8,16]:
    png(f"/tmp/v{H}.png",1,H,[[(y*10,0,0)] for y in range(H)])
    for tr in [2,3,4,6]:
        rows=render(f"/tmp/v{H}.png",2,tr)
        flat=[]
        for r,_ in rows: flat.extend(r[::2] if False else [])
        # rows each is (flat list per char pair) - we need sequence Y: bg0,fg0,bg1,fg1...
        seq=[]
        for r,_ in rows:
            # r is flat [bgR,fgR, bgR,fgR...] duplicate cols; take first col pair
            seq.append(r[0]); seq.append(r[1])
        print(f"V H={H} tr={tr} outH={tr*2} seq={seq}  p={[round(v/10,2) for v in seq]}")
print()
for W in [4,8,16]:
    png(f"/tmp/h{W}.png",W,1,[[(x*10,0,0) for x in range(W)]])
    for tc in [2,4,8]:
        rows=render(f"/tmp/h{W}.png",tc,2)
        seq=rows[0][0][::2]  # bg only per col? flat bg,fg repeating; take bg of each char? our flat interleaves
        # rows[0][0] is [bg0,fg0,bg1,fg1...], bg list = even indices
        bg=rows[0][0][0::2]
        print(f"H W={W} tc={tc} seq_bg={bg} p={[round(v/10,2) for v in bg]}")
PY"}

