package main
import ("image";"image/color";"image/png";"os";"fmt")
func save(path string,w,h int, fx func(x,y int) uint8){
 img:=image.NewRGBA(image.Rect(0,0,w,h))
 for y:=0;y<h;y++{ for x:=0;x<w;x++{ v:=fx(x,y); img.Set(x,y,color.RGBA{v,0,0,255})}}
 f,_:=os.Create(path); defer f.Close(); png.Encode(f,img)
}
func main(){
 for i:=0;i<8;i++{
   ii:=i
   save(fmt.Sprintf("/tmp/imp_v_%d.png",i),8,8, func(x,y int) uint8{ if y==ii {return 255}; return 0})
   save(fmt.Sprintf("/tmp/imp_h_%d.png",i),8,8, func(x,y int) uint8{ if x==ii {return 255}; return 0})
 }
 // also 16 height impulses
 for i:=0;i<16;i++{
   ii:=i
   save(fmt.Sprintf("/tmp/imp16_v_%d.png",i),16,16, func(x,y int) uint8{ if y==ii {return 255}; return 0})
 }
}
