import subprocess,re
def render(path,tc,tr):
    p=subprocess.run(["/workspace/executable","-tc",str(tc),"-tr",str(tr),path],capture_output=True)
    out=p.stdout.decode()
    grid=[]
    for line in out.strip().split("\n"):
        cells=re.findall(r"48;2;(\d+);",line)
        # cells sequence interleaved bg/fg? find all
        grid.append(line)
    # parse cells properly
    rows=[]
    for line in out.strip().split("\n"):
        cells=re.findall(r"48;2;(\d+);(\d+);(\d+)m\x1b\[38;2;(\d+);(\d+);(\d+)m",line)
        rows.append(cells)
    return rows

def hseq(path,tc,tr):
    rows=render(path,tc,tr)
    return [int(c[0]) for c in rows[0]] if rows else []
def vseq(path,tc,tr):
    rows=render(path,tc,tr)
    s=[]
    for r in rows:
        s.append(int(r[0][0])); s.append(int(r[0][3]))
    return s

