import pty,os,subprocess,struct,fcntl,termios,re
def run_pty(cols,rows,args, mode="stdout"):
    master,slave=pty.openpty()
    fcntl.ioctl(slave,termios.TIOCSWINSZ,struct.pack("HHHH",rows,cols,0,0))
    kw={}
    if mode=="stdout":
        kw=dict(stdout=slave,stderr=subprocess.PIPE,stdin=subprocess.PIPE)
    elif mode=="stdin":
        kw=dict(stdout=subprocess.PIPE,stderr=subprocess.PIPE,stdin=slave)
    elif mode=="both":
        kw=dict(stdout=slave,stderr=slave,stdin=slave)
    p=subprocess.Popen(["/workspace/executable"]+args,close_fds=True,**kw)
    os.close(slave)
    out=b""
    if mode in ("stdout","both"):
        while True:
            try:
                d=os.read(master,4096)
                if not d: break
                out+=d
            except OSError: break
        stdout=out; stderr=b""
    else:
        stdout,stderr=p.communicate()
    p.wait(); os.close(master)
    if mode=="stdin":
        stdout,stderr=p.stdout, p.stderr # not
    return p.returncode,stdout,stderr

for mode in ["stdout","stdin"]:
    for args,label in [([],"no flags"),(["-tc","5","-tr","3"],"tc5tr3"),(["-tr","3"],"tr3"),(["-tc","5"],"tc5")]:
