    if name=="lanczos2": return (lambda x: 0 if abs(x)>=2 else sinc(x)*sinc(x/2),2)
    if name=="bilinear": return (lambda x: max(0,1-abs(x)),1)
    if name=="catmull":
        def f(x):
            x=abs(x)
            return (1.5*x**3-2.5*x**2+1) if x<=1 else (-0.5*x**3+2.5*x**2-4*x+2) if x<=2 else 0
        return (f,2)
