        def f(x):
            x=abs(x)
            return (4-6*x*x+3*x**3)/6 if x<1 else ((2-x)**3/6 if x<2 else 0)
        return (f,2)
    if name=="mitchell":
        def f(x):
            x=abs(x); B=C=1/3
            if x<1: return ((12-9*B-6*C)*x**3+(-18+12*B+6*C)*x**2+(6-2*B))/6
            if x<2: return ((-B-6*C)*x**3+(6*B+30*C)*x**2+(-12*B-48*C)*x+(8*B+24*C))/6
            return 0
        return (f,2)
