        for j in range(int(math.floor(c-supp)),int(math.ceil(c+supp))+1):
            if 0<=j<N:
                w=func((j-c)/max(1,scale)); tot+=w; val+=w*src[j]
        out.append(max(0,min(255,val/tot)))
    return out
