obs=[107,99,127,156,148,185,127,123,100]
def conv(seq, kern, edge="clamp"):
    out=[]
    mid=len(kern)//2
    for i in range(len(seq)):
        tot=0;val=0
        for k,w in enumerate(kern):
            j=i+k-mid
            if edge=="clamp": jj=min(max(j,0),len(seq)-1)
            elif edge=="zero":
                if not (0<=j<len(seq)): continue
                jj=j
            else: jj=j if 0<=j<len(seq) else None
            if jj is not None:
                tot+=w; val+=w*seq[jj]
        out.append(val/tot)
    return out
for kern in [[1/6,4/6,1/6],[0.25,0.5,0.25],[1/8,6/8,1/8],[0.1,0.8,0.1],[0.15,0.7,0.15],[0.2,0.6,0.2]]:
    for edge in ["clamp","zero"]:
        r=[round(x) for x in conv(avg,kern,edge)][:9]
        print(kern,edge,r,"err",sum(abs(r[i]-obs[i]) for i in range(9)))
