import math
def sinc(x): return 1 if x==0 else math.sin(math.pi*x)/(math.pi*x)
def K(name,x):
    x0=x; x=abs(x)
    if name=="lanczos3": return 0 if x>=3 else sinc(x0)*sinc(x0/3)
    if name=="lanczos2": return 0 if x>=2 else sinc(x0)*sinc(x0/2)
    if name=="bilinear": return max(0,1-x) if x<1 else 0
    if name=="catmull":
        if x<=1: return 1.5*x**3-2.5*x**2+1
        if x<=2: return -0.5*x**3+2.5*x**2-4*x+2
        return 0
    if name=="bspline":
        if x<1: return (4-6*x*x+3*x**3)/6
        if x<2: return (2-x)**3/6
        return 0
    if name=="mitchell":
        B=C=1/3
        if x<1: return ((12-9*B-6*C)*x**3+(-18+12*B+6*C)*x**2+(6-2*B))/6
        if x<2: return ((-B-6*C)*x**3+(6*B+30*C)*x**2+(-12*B-48*C)*x+(8*B+24*C))/6
        return 0
    if name=="hermite":
        return (2*x-3)*x*x+1 if x<1 else 0
    raise
SUPPORT={"lanczos3":3,"lanczos2":2,"bilinear":1,"catmull":2,"bspline":2,"mitchell":2,"hermite":1}
