import math, subprocess, re, random, struct, zlib

def sinc(x): return 1.0 if x==0 else math.sin(math.pi*x)/(math.pi*x)
def l3(x): return 0.0 if abs(x)>=3 else sinc(x)*sinc(x/3)

def weights(N,M):
    # returns list per output: list of (src_idx, weight_normalized_inbounds)
    scale=N/M
    factor=max(1.0,scale)
    out=[]
    for i in range(M):
        c=(i+0.5)*scale-0.5
        supp=3*factor
        lst=[]
        tot=0.0
        for j in range(int(math.floor(c-supp)), int(math.ceil(c+supp))+1):
            if 0<=j<N:
                w=l3((j-c)/factor); lst.append((j,w)); tot+=w
        if tot!=0:
            lst=[(j,w/tot) for j,w in lst]
        out.append(lst)
    return out

def resize_img(img, Wd, Hd, order='HV', inter_clip=True, inter_bits=None, final_round='round'):
    # img: list rows list of (r,g,b) floats/ints 0-255 scale
    h=len(img); w=len(img[0])
    wx=weights(w,Wd); wy=weights(h,Hd)
    def pass_h(src, Wd):
        out=[]
        for row in src:
            orow=[]
            for lst in wx:
                vals=[0.0,0.0,0.0]
                for j,wgt in lst:
                    px=row[j]
                    for c in range(3): vals[c]+=wgt*px[c]
                orow.append(tuple(vals))
            out.append(orow)
        return out
    def pass_v(src, Hd):
        out=[]
        # src has width uniform
        for lst in wy:
            orow=[]
            width=len(src[0])
            for x in range(width):
                vals=[0.0,0.0,0.0]
                for j,wgt in lst:
                    px=src[j][x]
                    for c in range(3): vals[c]+=wgt*px[c]
                orow.append(tuple(vals))
            out.append(orow)
        return out
    def clamp_quant(img, bits):
        out=[]
        for row in img:
            orow=[]
            for px in row:
                vals=[]
                for v in px:
                    v=max(0.0,min(255.0,v))
                    if bits==16:
                        # quantize to 16-bit unit in 255 scale: step 1/257? representing uint16 then back to 8bit high byte later
                        # Store as level out of 65535 converted to 0-255 float with quantization to integer 16-bit
                        q=int(round(v*257.0))  # 0..65535 (v*257 maybe)
                        if q>65535: q=65535
                        v=q/257.0
                    elif bits==8:
                        v=int(round(v))
                    vals.append(v)
                orow.append(tuple(vals))
            out.append(orow)
        return out
    if order=='HV':
        tmp=pass_h(img,Wd)
        if inter_clip or inter_bits: tmp=clamp_quant(tmp, inter_bits)
        out=pass_v(tmp,Hd)
    else:
        tmp=pass_v(img,Hd)
        if inter_clip or inter_bits: tmp=clamp_quant(tmp, inter_bits)
        out=pass_h(tmp,Wd)
    # final convert clamp round/trunc high byte equiv: we keep 0-255, round or trunc towards? final 8bit in orig is (16bit>>8) equiv approx trunc(v*257/256?) hmm
    res=[]
    for row in out:
        orow=[]
        for px in row:
            vals=[]
            for v in px:
                v=max(0.0,min(255.0,v))
                if final_round=='round': iv=int(round(v))
                elif final_round=='trunc': iv=int(v)
                elif final_round=='hi': iv=int(v*257)//256 if v<255 else 255  # approx
                else: iv=int(round(v))
                vals.append(min(255,max(0,iv)))
            orow.append(tuple(vals))
        res.append(orow)
    return res

def png_bytes(w,h,pixels):
    raw=b""
    for y in range(h):
        raw+=b"\x00"
        for x in range(w): raw+=bytes(pixels[y][x])
    def chunk(t,d): return struct.pack(">I",len(d))+t+d+struct.pack(">I", zlib.crc32(t+d)&0xffffffff)
    return b"\x89PNG\r\n\x1a\n"+chunk(b"IHDR",struct.pack(">IIBBBBB",w,h,8,2,0,0,0))+chunk(b"IDAT",zlib.compress(raw))+chunk(b"IEND",b"")

def orig_pixels(path,tc,tr):
    p=subprocess.run(["/workspace/executable","-tc",str(tc),"-tr",str(tr),path],capture_output=True)
    rows=[]
    for line in p.stdout.decode().strip().split("\n"):
        cells=re.findall(r"48;2;(\d+);(\d+);(\d+)m\x1b\[38;2;(\d+);(\d+);(\d+)m",line)
        for c in cells:
            rows.append(tuple(map(int,c[:3]))); rows.append(tuple(map(int,c[3:6])))
        # ordering: we need pixel rows, not flatten per line? Build differently below
    # redo grid
    grid=[]
    for line in p.stdout.decode().strip().split("\n"):
        cells=re.findall(r"48;2;(\d+);(\d+);(\d+)m\x1b\[38;2;(\d+);(\d+);(\d+)m",line)
        upper=[tuple(map(int,c[:3])) for c in cells]; lower=[tuple(map(int,c[3:6])) for c in cells]
        grid.append(upper); grid.append(lower)
    return grid

def candidate_grid(pixels,tc,tr, **kw):
    Hd=(tr+1)*2
    R=resize_img(pixels, tc, Hd, **kw)
    return R[2:]

def compare(pixels,tc,tr, **kw):
    open("/tmp/cand.png","wb").write(png_bytes(len(pixels[0]), len(pixels), pixels))
    orig=orig_pixels("/tmp/cand.png",tc,tr)
    cand=candidate_grid(pixels,tc,tr,**kw)
    if len(orig)!=len(cand) or len(orig[0])!=len(cand[0]):
        return ("dims",len(orig),len(cand))
    total=0; exact=0; maxd=0; sums=0
    for y in range(len(orig)):
