import math, subprocess, re, random, struct, zlib
exec(open('/tmp/sim.py').read().split("# test random image")[0])  # defines resize_img etc but resize_img is 3 channels

# Extend resize to 4 channels reusing weights from sim.py functions: rewrite generic
def resize4(img,Wd,Hd):
    h=len(img); w=len(img[0])
    wx=weights(w,Wd); wy=weights(h,Hd)
    def clamp_round(vals):
        out=[]
        for v in vals:
            v=max(0.0,min(255.0,v)); out.append(int(round(v)))
        return tuple(out)
    # H pass
    tmp=[]
    for row in img:
        orow=[]
        for lst in wx:
            vals=[0.0]*4
            for j,wgt in lst:
                for c in range(4): vals[c]+=wgt*row[j][c]
            orow.append(clamp_round(vals))
        tmp.append(orow)
    out=[]
    for lst in wy:
        orow=[]
        for x in range(Wd):
            vals=[0.0]*4
            for j,wgt in lst:
                for c in range(4): vals[c]+=wgt*tmp[j][x][c]
            orow.append(clamp_round(vals))
        out.append(orow)
    return out

def png_rgba(w,h,pixels):
    raw=b""
    for y in range(h):
        raw+=b"\x00"
        for x in range(w): raw+=bytes(pixels[y][x])
    def chunk(t,d): return struct.pack(">I",len(d))+t+d+struct.pack(">I", zlib.crc32(t+d)&0xffffffff)
    return b"\x89PNG\r\n\x1a\n"+chunk(b"IHDR",struct.pack(">IIBBBBB",w,h,8,6,0,0,0))+chunk(b"IDAT",zlib.compress(raw))+chunk(b"IEND",b"")

def blend(pixel, matte=(0,0,0)):
    R,G,B,A=pixel
    out=[]
    for i,col in enumerate((R,G,B)):
        r_pre=(col*257 * A)//255
        a16=A*257; m16=matte[i]*257
        out16=r_pre + (m16*(65535-a16))//65535
        out.append(out16>>8)
