// blendWithMatte converts an NRGBA pixel (as stored after resizing) to an
// opaque 8-bit RGB triple, compositing over matte when translucent.
// This follows Go's 16-bit premultiplied colour arithmetic.
func blendWithMatte(p color.NRGBA, matte color.RGBA) [3]uint8 {
	r, g, b, a := p.RGBA()
	if a != 0xffff {
		mr, mg, mb, _ := matte.RGBA()
		inv := uint32(0xffff) - a
		r += (mr * inv) / 0xffff
		g += (mg * inv) / 0xffff
		b += (mb * inv) / 0xffff
	}
	return [3]uint8{uint8(r >> 8), uint8(g >> 8), uint8(b >> 8)}
}

