	"os"
	"syscall"
	"unsafe"
)

type winsize struct {
	Rows uint16
	Cols uint16
	X    uint16
	Y    uint16
}

func terminalSize() (int, int, error) {
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(), syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 0, 0, errors.New("not a terminal")
	}
	return int(ws.Cols), int(ws.Rows), nil
}

func isTerminal() bool {
	// TCGETS ioctl succeeds only on a terminal device.
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(), 0x5401 /* TCGETS on Linux */, uintptr(unsafe.Pointer(&ws)))
	return errno == 0
}
