}

type ansImage struct {
	w      int
	h      int
	pix    []ansiPixel
	dither bool
	noBG   bool
	matte  rgb
}

func toNRGBA(img image.Image) *image.NRGBA {
	b := img.Bounds()
	w, h := b.Dx(), b.Dy()
	if w < 0 {
		w = 0
	}
	if h < 0 {
		h = 0
	}
	out := image.NewNRGBA(image.Rect(0, 0, w, h))
	drawimg.Draw(out, out.Bounds(), img, b.Min, drawimg.Src)
	return out
}

func sinc(x float64) float64 {
	if x == 0 {
		return 1
	}
	return math.Sin(math.Pi*x) / (math.Pi * x)
}

func lanczos3(x float64) float64 {
	if x < -3 || x > 3 {
		return 0
	}
	if x == 0 {
		return 1
	}
	return sinc(x) * sinc(x/3)
}

type contrib struct {
	idx int
	w   float64
}

func makeWeights(srcN, dstN int) [][]contrib {
	if srcN <= 0 || dstN <= 0 {
		return nil
	}
	scale := float64(srcN) / float64(dstN)
	factor := math.Max(1, scale)
	support := 3 * factor
	out := make([][]contrib, dstN)
	for i := 0; i < dstN; i++ {
		center := (float64(i)+0.5)*scale - 0.5
		start := int(math.Floor(center - support))
		end := int(math.Ceil(center + support))
		var lst []contrib
		sum := 0.0
		for j := start; j <= end; j++ {
			if j < 0 || j >= srcN {
				continue
			}
			w := lanczos3((float64(j) - center) / factor)
			lst = append(lst, contrib{j, w})
			sum += w
		}
		if sum != 0 {
			for k := range lst {
				lst[k].w /= sum
			}
		}
		out[i] = lst
	}
	return out
}

func clampRoundByte(v float64) uint8 {
	if v <= 0 {
		return 0
	}
	if v >= 255 {
		return 255
	}
	return uint8(math.Floor(v + 0.5))
}

// storePremult converts accumulated premultiplied colour sums (in 0..255
// space, alpha likewise) into an NRGBA pixel, mirroring the behaviour
// observed from the reference resampler.
func storePremult(pr, pg, pb, a float64) color.NRGBA {
	aByte := clampRoundByte(a)
	if aByte == 0 {
		return color.NRGBA{0, 0, 0, 0}
	}
	if a == 0 {
		return color.NRGBA{0, 0, 0, 0}
	}
	return color.NRGBA{
		clampRoundByte(pr / a * 255),
		clampRoundByte(pg / a * 255),
		clampRoundByte(pb / a * 255),
		aByte,
	}
}

func resizeNRGBA(src *image.NRGBA, dstW, dstH int) *image.NRGBA {
	if dstW <= 0 || dstH <= 0 {
		return image.NewNRGBA(image.Rectangle{})
	}
	srcW := src.Bounds().Dx()
	srcH := src.Bounds().Dy()
	if srcW <= 0 || srcH <= 0 {
		return image.NewNRGBA(image.Rect(0, 0, dstW, dstH))
	}
	wx := makeWeights(srcW, dstW)
	wy := makeWeights(srcH, dstH)

	// Horizontal pass.
	tmp := image.NewNRGBA(image.Rect(0, 0, dstW, srcH))
	for y := 0; y < srcH; y++ {
		for x := 0; x < dstW; x++ {
			var pr, pg, pb, a float64
			for _, c := range wx[x] {
				p := src.NRGBAAt(c.idx, y)
				fa := float64(p.A)
				w := c.w
				pr += w * float64(p.R) * fa / 255
				pg += w * float64(p.G) * fa / 255
				pb += w * float64(p.B) * fa / 255
				a += w * fa
			}
			tmp.SetNRGBA(x, y, storePremult(pr, pg, pb, a))
		}
	}
	// Vertical pass.
	out := image.NewNRGBA(image.Rect(0, 0, dstW, dstH))
	for y := 0; y < dstH; y++ {
		for x := 0; x < dstW; x++ {
			var pr, pg, pb, a float64
			for _, c := range wy[y] {
				p := tmp.NRGBAAt(x, c.idx)
				fa := float64(p.A)
				w := c.w
				pr += w * float64(p.R) * fa / 255
				pg += w * float64(p.G) * fa / 255
				pb += w * float64(p.B) * fa / 255
				a += w * fa
			}
			out.SetNRGBA(x, y, storePremult(pr, pg, pb, a))
		}
	}
	return out
}

func cropCenter(src *image.NRGBA, w, h int) *image.NRGBA {
	sw := src.Bounds().Dx()
	sh := src.Bounds().Dy()
	ox := (sw - w) / 2
	oy := (sh - h) / 2
	if ox < 0 {
		ox = 0
	}
	if oy < 0 {
		oy = 0
	}
	out := image.NewNRGBA(image.Rect(0, 0, w, h))
	drawimg.Draw(out, out.Bounds(), src, image.Pt(ox, oy), drawimg.Src)
	return out
}

// scaledPixelImage returns the resized (and, for fill, cropped) pixel image
// whose dimensions are SW x SH.
func scaledPixelImage(src *image.NRGBA, cols, rows, scaleMode, k int) (*image.NRGBA, error) {
	iw := src.Bounds().Dx()
	ih := src.Bounds().Dy()
	boxW := cols
	boxH := (rows + 1) * k
	if cols < 2 || boxH < 2 {
		return nil, errANSImageSize
	}
	switch scaleMode {
	case 0: // resize
		return resizeNRGBA(src, boxW, boxH), nil
	case 1: // fill
		// Scale so both dimensions cover the box, then crop centrally.
		var sw, sh int
		// width/height comparisons with integers to avoid float artefacts.
		// Cover: if iw/boxW >= ih/boxH i.e. iw*boxH >= ih*boxW, height becomes boxH? Wait:
		// scale = max(boxW/iw, boxH/ih). The larger scale determines the equal side.
		if boxW*ih >= boxH*iw {
			// boxW/iw >= boxH/ih, width is the driving side scaled to boxW,
			// height = ceil(ih * boxW / iw)
			sw = boxW
			sh = (ih*boxW + iw - 1) / iw
		} else {
			sh = boxH
			sw = (iw*boxH + ih - 1) / ih
		}
		if sw < 2 || sh < 2 {
			return nil, errANSImageSize
		}
		resized := resizeNRGBA(src, sw, sh)
		return cropCenter(resized, boxW, boxH), nil
	case 2: // fit
		var sw, sh int
		if iw <= boxW && ih <= boxH {
			sw, sh = iw, ih
		} else if iw*boxH > ih*boxW {
			// width limiting
			sw = boxW
			sh = boxW * ih / iw
		} else {
			sh = boxH
			sw = boxH * iw / ih
		}
		if sw < 2 || sh < 2 {
			return nil, errANSImageSize
		}
		if sw == iw && sh == ih {
			// clone
			out := image.NewNRGBA(image.Rect(0, 0, iw, ih))
			drawimg.Draw(out, out.Bounds(), src, image.Pt(0, 0), drawimg.Src)
			return out, nil
		}
		return resizeNRGBA(src, sw, sh), nil
	}
	return nil, errANSImageSize
}

var ditherBlocks = []rune{' ', '░', '▒', '▓', '█'}
var ditherBlockCutoffs = []int{49, 101, 153, 205}
var ditherChars = []rune{' ', '.', ':', ';', '+', '=', 'x', 'X', '$', '&', '#'}
var ditherCharCutoffs = []int{24, 47, 70, 93, 116, 139, 162, 185, 208, 231}

func ditherCharFor(c rgb, mode int) rune {
	m := int(c.r)
	if int(c.g) > m {
		m = int(c.g)
	}
	if int(c.b) > m {
		m = int(c.b)
	}
	if mode == 1 {
		idx := 0
		for i, cut := range ditherBlockCutoffs {
			if m >= cut {
				idx = i + 1
			}
		}
		return ditherBlocks[idx]
	}
	idx := 0
	for i, cut := range ditherCharCutoffs {
		if m >= cut {
			idx = i + 1
		}
	}
	if idx >= len(ditherChars) {
		idx = len(ditherChars) - 1
	}
	return ditherChars[idx]
}

func newScaledFromImage(img image.Image, cols, rows int, matte color.RGBA, scaleMode, ditherMode int, noBG bool) (*ansImage, error) {
	src := toNRGBA(img)
	matteRGB := rgb{matte.R, matte.G, matte.B}

	if ditherMode == 0 {
		resized, err := scaledPixelImage(src, cols, rows, scaleMode, 2)
		if err != nil {
			return nil, err
		}
		sw := resized.Bounds().Dx()
		sh := resized.Bounds().Dy()
		pairs := sh / 2
		outRows := pairs - 1
		if outRows < 0 {
			outRows = 0
		}
		ans := &ansImage{w: sw, h: outRows, matte: matteRGB}
		ans.pix = make([]ansiPixel, 0, sw*outRows)
		for y := 0; y < outRows; y++ {
			pair := y + 1
			for x := 0; x < sw; x++ {
				up := blendWithMatte(resized.NRGBAAt(x, pair*2), matte)
				lo := blendWithMatte(resized.NRGBAAt(x, pair*2+1), matte)
				ans.pix = append(ans.pix, ansiPixel{
					bg:   rgb{up[0], up[1], up[2]},
					fg:   rgb{lo[0], lo[1], lo[2]},
					char: '▄',
				})
			}
		}
		if outRows == 0 {
			ans.w = sw
			ans.h = 0
			ans.pix = nil
		}
		return ans, nil
	}

	// Dithering modes: build from the classic (paired) scaled image by
	// averaging each pair into a single colour (first approximation of the
	// reference behaviour).
	resized, err := scaledPixelImage(src, cols, rows, scaleMode, 2)
	if err != nil {
		return nil, err
	}
	sw := resolvedWidth(resized)
	sh := resized.Bounds().Dy()
	pairs := sh / 2
	outRows := pairs - 1
	// For dithering output, the reference prints the first (pairs-1) merged
	// rows.
	if scaleMode == 0 || scaleMode == 1 {
		outRows = rows
		if outRows > pairs {
			outRows = pairs
		}
	} else {
		outRows = pairs - 1
	}
	if outRows < 0 {
		outRows = 0
	}
	ans := &ansImage{w: sw, h: outRows, dither: true, noBG: noBG, matte: matteRGB}
	ans.pix = make([]ansiPixel, 0, sw*outRows)
	for y := 0; y < outRows; y++ {
		for x := 0; x < sw; x++ {
			up := blendWithMatte(resized.NRGBAAt(x, y*2), matte)
			lo := blendWithMatte(resized.NRGBAAt(x, y*2+1), matte)
			avg := rgb{
				uint8((int(up[0]) + int(lo[0])) / 2),
				uint8((int(up[1]) + int(lo[1])) / 2),
				uint8((int(up[2]) + int(lo[2])) / 2),
			}
			ans.pix = append(ans.pix, ansiPixel{
				bg:   matteRGB,
				fg:   avg,
				char: ditherCharFor(avg, ditherMode),
			})
		}
	}
	return ans, nil
}

func resolvedWidth(img *image.NRGBA) int { return img.Bounds().Dx() }

func (a *ansImage) render(goOutput bool) string {
	var sb strings.Builder
	for y := 0; y < a.h; y++ {
		var line strings.Builder
		for x := 0; x < a.w; x++ {
			p := a.pix[y*a.w+x]
			if a.dither && a.noBG {
				line.WriteString(colorSeq(false, p.fg))
			} else {
				line.WriteString(colorSeq(true, p.bg))
				line.WriteString(colorSeq(false, p.fg))
			}
			line.WriteRune(p.char)
		}
		line.WriteString("\x1b[0m")
		if goOutput {
			s := strings.ReplaceAll(line.String(), "\x1b", "\\033")
			sb.WriteString("fmt.Print(\"")
			sb.WriteString(s)
			sb.WriteString("\\n\")\n")
		} else {
			sb.WriteString(line.String())
			sb.WriteString("\n")
		}
	}
	return sb.String()
}

func colorSeq(bg bool, c rgb) string {
	t := "38"
	if bg {
		t = "48"
	}
	return "\x1b[" + t + ";2;" + itoa(int(c.r)) + ";" + itoa(int(c.g)) + ";" + itoa(int(c.b)) + "m"
}

func itoa(v int) string {
	if v == 0 {
		return "0"
	}
	var buf [8]byte
	i := len(buf)
	for v > 0 {
		i--
		buf[i] = byte('0' + v%10)
		v /= 10
	}
	return string(buf[i:])
}
