var errUnsupportedBMP = errors.New("bmp: unsupported BMP image")

// ---------------- BMP ----------------

type bmpHeader struct {
	offBits   uint32
	dibSize   uint32
	width     int32
	height    int32
	planes    uint16
	bpp       uint16
	compress  uint32
	colorsUsed uint32
}

func readBMPHeader(r io.Reader) (bmpHeader, []byte, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return bmpHeader{}, nil, err
	}
	// We return data for the pixel stage; header parsing needs at least
	// the 14-byte file header plus 4 bytes of DIB size.
	if len(data) < 18 {
		return bmpHeader{}, data, io.ErrUnexpectedEOF
	}
	h := bmpHeader{}
	h.offBits = binary.LittleEndian.Uint32(data[10:14])
	h.dibSize = binary.LittleEndian.Uint32(data[14:18])
	if h.dibSize != 40 {
		return h, data, errUnsupportedBMP
	}
	if len(data) < 14+40 {
		return h, data, io.ErrUnexpectedEOF
	}
	dib := data[14:54]
	h.width = int32(binary.LittleEndian.Uint32(dib[4:8]))
	h.height = int32(binary.LittleEndian.Uint32(dib[8:12]))
	h.planes = binary.LittleEndian.Uint16(dib[12:14])
	h.bpp = binary.LittleEndian.Uint16(dib[14:16])
	h.compress = binary.LittleEndian.Uint32(dib[16:20])
	h.colorsUsed = binary.LittleEndian.Uint32(dib[32:36])
	if h.compress != 0 {
		return h, data, errUnsupportedBMP
	}
	if h.bpp != 8 && h.bpp != 24 && h.bpp != 32 {
		return h, data, errUnsupportedBMP
	}
	return h, data, nil
}

func decodeBMPConfig(r io.Reader) (image.Config, error) {
	h, _, err := readBMPHeader(r)
	if err != nil {
		return image.Config{}, err
	}
	height := int(h.height)
	if height < 0 {
		height = -height
	}
	cm := color.Color(color.RGBA{})
	_ = cm
	return image.Config{ColorModel: color.RGBAModel, Width: int(h.width), Height: height}, nil
}

func decodeBMP(r io.Reader) (image.Image, error) {
	h, data, err := readBMPHeader(r)
	if err != nil {
		return nil, err
	}
	w := int(h.width)
	heightSigned := int(h.height)
	topDown := heightSigned < 0
	hgt := heightSigned
	if hgt < 0 {
		hgt = -hgt
	}
	if w < 0 {
		w = -w
	}
	img := image.NewRGBA(image.Rect(0, 0, w, hgt))
	// Palette for 8bpp.
	var palette []color.RGBA
	if h.bpp == 8 {
		n := int(h.colorsUsed)
		if n == 0 {
			// Derive from offset if possible, else 256.
			avail := int(h.offBits) - 14 - int(h.dibSize)
			if avail >= 4 {
				n = avail / 4
			} else {
				n = 256
			}
		}
		if n > 256 {
			n = 256
		}
		palette = make([]color.RGBA, n)
		base := 14 + int(h.dibSize)
		for i := 0; i < n; i++ {
			if base+4*i+4 > len(data) {
				return nil, io.ErrUnexpectedEOF
			}
			b := data[base+4*i]
			g := data[base+4*i+1]
			rr := data[base+4*i+2]
			palette[i] = color.RGBA{rr, g, b, 255}
		}
	}
	rowSize := 0
	switch h.bpp {
	case 8:
		rowSize = ((w + 3) / 4) * 4
	case 24:
		rowSize = ((w*3 + 3) / 4) * 4
	case 32:
		rowSize = w * 4
	}
	off := int(h.offBits)
	for fileRow := 0; fileRow < hgt; fileRow++ {
		y := fileRow
		if !topDown {
			y = hgt - 1 - fileRow
		}
		if off+rowSize*fileRow+rowSize > len(data) && hgt > 0 {
			// Allow exactly-at-EOF checks per row below.
			if off+rowSize*fileRow >= len(data) {
				return nil, io.ErrUnexpectedEOF
			}
		}
		rowStart := off + rowSize*fileRow
		if rowStart < 0 || rowStart >= len(data) {
			return nil, io.ErrUnexpectedEOF
		}
		for x := 0; x < w; x++ {
			var c color.RGBA
			switch h.bpp {
			case 8:
				if rowStart+x >= len(data) {
					return nil, io.ErrUnexpectedEOF
				}
				idx := int(data[rowStart+x])
				if idx < len(palette) {
					c = palette[idx]
				} else {
					c = color.RGBA{0, 0, 0, 255}
				}
			case 24:
				p := rowStart + x*3
				if p+3 > len(data) {
					return nil, io.ErrUnexpectedEOF
				}
				c = color.RGBA{data[p+2], data[p+1], data[p], 255}
			case 32:
				p := rowStart + x*4
				if p+4 > len(data) {
					return nil, io.ErrUnexpectedEOF
				}
				c = color.RGBA{data[p+2], data[p+1], data[p], 255}
			}
			img.Set(x, y, c)
		}
	}
	return img, nil
}

// ---------------- TIFF ----------------

type tiffReader struct {
	data  []byte
	order binary.ByteOrder
	ifd   map[uint16][]uint32
	// raw values for tags that need byte slices are reparsed on demand
}

func (t *tiffReader) parse() error {
	if len(t.data) < 8 {
		return io.ErrUnexpectedEOF
	}
	switch string(t.data[:2]) {
	case "II":
		t.order = binary.LittleEndian
	case "MM":
		t.order = binary.BigEndian
	default:
		return errors.New("tiff: invalid format")
	}
	if t.order.Uint16(t.data[2:4]) != 42 {
		return errors.New("tiff: invalid format")
	}
	off := int(t.order.Uint32(t.data[4:8]))
	if off < 0 || off+2 > len(t.data) {
		return io.EOF
	}
	n := int(t.order.Uint16(t.data[off : off+2]))
	t.ifd = make(map[uint16][]uint32)
	pos := off + 2
	for i := 0; i < n; i++ {
		if pos+12 > len(t.data) {
			return io.ErrUnexpectedEOF
		}
		tag := t.order.Uint16(t.data[pos : pos+2])
		typ := t.order.Uint16(t.data[pos+2 : pos+4])
		count := int(t.order.Uint32(t.data[pos+4 : pos+8]))
		valField := t.data[pos+8 : pos+12]
		vals := make([]uint32, 0, count)
		typeSize := map[uint16]int{1: 1, 2: 1, 3: 2, 4: 4, 5: 8, 12: 8}[typ]
		if typeSize == 0 {
			typeSize = 1
		}
		total := typeSize * count
		var raw []byte
		if total <= 4 {
			raw = valField[:total]
		} else {
			voff := int(t.order.Uint32(valField))
			if voff < 0 || voff+total > len(t.data) {
				return io.ErrUnexpectedEOF
			}
			raw = t.data[voff : voff+total]
		}
		for j := 0; j < count; j++ {
			switch typ {
			case 3:
				if 2*j+2 <= len(raw) {
					vals = append(vals, uint32(t.order.Uint16(raw[2*j:])))
				}
			case 4:
				if 4*j+4 <= len(raw) {
					vals = append(vals, t.order.Uint32(raw[4*j:]))
				}
			default:
				if j < len(raw) {
					vals = append(vals, uint32(raw[j]))
				}
			}
		}
		t.ifd[tag] = vals
		pos += 12
	}
	return nil
}

func (t *tiffReader) get(tag uint16, def uint32) uint32 {
	if v, ok := t.ifd[tag]; ok && len(v) > 0 {
		return v[0]
	}
	return def
}
func (t *tiffReader) getAll(tag uint16) []uint32 { return t.ifd[tag] }

func decodeTIFFConfig(r io.Reader) (image.Config, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return image.Config{}, err
	}
	tr := &tiffReader{data: data}
	if err := tr.parse(); err != nil {
		return image.Config{}, err
	}
	w := int(tr.get(256, 0))
	h := int(tr.get(257, 0))
	return image.Config{ColorModel: color.RGBAModel, Width: w, Height: h}, nil
}

func packBitsDecode(src []byte) []byte {
	var out []byte
	i := 0
	for i < len(src) {
		n := int(int8(src[i]))
		i++
		switch {
		case n >= 0:
			cnt := n + 1
			if i+cnt > len(src) {
				out = append(out, src[i:]...)
				i = len(src)
			} else {
				out = append(out, src[i:i+cnt]...)
				i += cnt
			}
		case n >= -127:
			if i < len(src) {
				for k := 0; k < -n+1; k++ {
					out = append(out, src[i])
				}
				i++
			}
		default:
			// -128: no-op
		}
	}
	return out
}

func lzwDecodeTIFF(src []byte) ([]byte, error) {
	// TIFF LZW: MSB-first, clear=256, EOI=257, early change.
	const clearCode = 256
	const eoiCode = 257
	var out []byte
	bitPos := 0
	readCode := func(width int) (int, bool) {
		if bitPos+width > len(src)*8 {
			return 0, false
		}
		val := 0
		for i := 0; i < width; i++ {
			byteIdx := (bitPos + i) / 8
			bitIdx := 7 - ((bitPos + i) % 8)
			val = (val << 1) | int((src[byteIdx]>>bitIdx)&1)
		}
		bitPos += width
		return val, true
	}
	table := make([][]byte, 4096)
	reset := func() {
		for i := 0; i < 256; i++ {
			table[i] = []byte{byte(i)}
		}
		for i := 256; i < 4096; i++ {
			table[i] = nil
		}
	}
	reset()
	next := 258
	width := 9
	var prev []byte
	for {
		if next >= (1<<width)-1 && width < 12 {
			width++
		}
		code, ok := readCode(width)
		if !ok {
			break
		}
		if code == clearCode {
			reset()
			next = 258
			width = 9
			prev = nil
			continue
		}
		if code == eoiCode {
			break
		}
		var entry []byte
		if code < next && table[code] != nil {
			entry = table[code]
		} else if code == next && prev != nil {
			entry = append(append([]byte{}, prev...), prev[0])
		} else {
			return out, errors.New("tiff: invalid LZW code")
		}
		out = append(out, entry...)
		if prev != nil && next < 4096 {
			ent := make([]byte, 0, len(prev)+1)
			ent = append(ent, prev...)
			ent = append(ent, entry[0])
			table[next] = ent
			next++
		}
		prev = append([]byte{}, entry...)
	}
	return out, nil
}

func decodeTIFF(r io.Reader) (image.Image, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	tr := &tiffReader{data: data}
	if err := tr.parse(); err != nil {
		return nil, err
	}
	w := int(tr.get(256, 0))
	h := int(tr.get(257, 0))
	if w <= 0 || h <= 0 {
		return nil, errors.New("tiff: invalid image size")
	}
	bps := tr.getAll(258)
	if len(bps) == 0 {
		bps = []uint32{1}
	}
	compression := tr.get(259, 1)
	photometric := tr.get(262, 1)
	stripOffsets := tr.getAll(273)
	samplesPerPixel := int(tr.get(277, 1))
	rowsPerStrip := int(tr.get(278, 0))
	if rowsPerStrip == 0 {
		rowsPerStrip = h
	}
	stripByteCounts := tr.getAll(279)
	planar := tr.get(284, 1)
	predictor := tr.get(317, 1)
	_ = predictor

	// Assemble strip data (concatenated in strip order). For planar=2 the
	// strips are per-channel planes; handled below by keeping them separate.
	var raw bytes.Buffer
	var planeData [][]byte
	if planar == 2 {
		planeData = make([][]byte, samplesPerPixel)
	}
	for i, offv := range stripOffsets {
		off := int(offv)
		var cnt int
		if i < len(stripByteCounts) {
			cnt = int(stripByteCounts[i])
		} else if off < len(data) {
			cnt = len(data) - off
		}
		if off < 0 || off >= len(data) {
			return nil, io.ErrUnexpectedEOF
		}
		if off+cnt > len(data) {
			cnt = len(data) - off
		}
		chunk := data[off : off+cnt]
		var dec []byte
		switch compression {
		case 1:
			dec = chunk
		case 32773:
			dec = packBitsDecode(chunk)
		case 5:
			d, err := lzwDecodeTIFF(chunk)
			if err != nil {
				return nil, err
			}
			dec = d
		case 8, 32946:
			zr, err := zlib.NewReader(bytes.NewReader(chunk))
			if err != nil {
				return nil, err
			}
			dec, err = io.ReadAll(zr)
			zr.Close()
			if err != nil {
				return nil, err
			}
		default:
			return nil, errors.New("tiff: unsupported compression")
		}
		if planar == 2 && samplesPerPixel > 0 {
			stripsPerPlane := (h + rowsPerStrip - 1) / rowsPerStrip
			plane := 0
			if stripsPerPlane > 0 {
				plane = i / stripsPerPlane
			}
			if plane < len(planeData) {
				planeData[plane] = append(planeData[plane], dec...)
			}
		} else {
			raw.Write(dec)
		}
	}
	pix := raw.Bytes()

	// Predictor 2: horizontal differencing.
	bitsPerSample0 := int(bps[0])
	if predictor == 2 && bitsPerSample0 >= 8 {
		bytesPerSample := bitsPerSample0 / 8
		rowBytes := 0
		if planar == 2 {
			rowBytes = w * bytesPerSample
			for p := range planeData {
				for yy := 0; yy < h; yy++ {
					base := yy * rowBytes
					for xx := bytesPerSample; xx < rowBytes; xx++ {
						if base+xx < len(planeData[p]) && base+xx >= 0 {
							// handled below per byte with component stride
						}
						_ = xx
					}
				}
				_ = p
			}
		} else {
			rowBytes = w * samplesPerPixel * bytesPerSample
			stride := samplesPerPixel * bytesPerSample
			for yy := 0; yy < h; yy++ {
				base := yy * rowBytes
				for xx := stride; xx < rowBytes; xx++ {
					if base+xx < len(pix) {
						pix[base+xx] = pix[base+xx] + pix[base+xx-stride]
					}
				}
			}
		}
	}

	// Color map for palette images.
	var palette []color.RGBA
	if cm := tr.getAll(320); len(cm) > 0 {
		n := len(cm) / 3
		palette = make([]color.RGBA, n)
		for i := 0; i < n; i++ {
			palette[i] = color.RGBA{uint8(cm[i] >> 8), uint8(cm[i+n] >> 8), uint8(cm[i+2*n] >> 8), 255}
		}
	}

	img := image.NewRGBA(image.Rect(0, 0, w, h))
	// Helpers to fetch a sample value.
	getSampleChunky := func(x, y, s int) (uint32, int) {
		// returns value and bits
		bpsv := 8
		if s < len(bps) {
			bpsv = int(bps[s])
		} else if len(bps) > 0 {
			bpsv = int(bps[0])
		}
		if bpsv == 8 {
			idx := (y*w + x) * samplesPerPixel
			if planar == 2 {
				// not chunky
				return 0, 8
			}
			if idx+s < len(pix) {
				return uint32(pix[idx+s]), 8
			}
			return 0, 8
		}
		if bpsv == 16 {
			idx := ((y*w + x) * samplesPerPixel) + s
			if 2*idx+1 < len(pix) {
				return uint32(binary.BigEndian.Uint16(pix[2*idx:])), 16
			}
			return 0, 16
		}
		// Sub-byte / other bit depths: unpack from bitstream (chunky)
		totalBits := 0
		// compute bit offset
		samplesBefore := (y*w + x) * samplesPerPixel
		bitOff := 0
		// Sum bits for simplicity assuming uniform bps
		bitOff = (samplesBefore + s) * bpsv
		_ = totalBits
		byteIdx := bitOff / 8
		shift := uint(8 - (bitOff % 8) - bpsv)
		if byteIdx < len(pix) {
			mask := uint32((1 << bpsv) - 1)
			if bpsv <= 8 {
				return (uint32(pix[byteIdx]) >> shift) & mask, bpsv
			}
		}
		return 0, bpsv
	}
	getSamplePlanar := func(x, y, s int) uint32 {
		bpsv := 8
		if len(bps) > 0 {
			if s < len(bps) {
				bpsv = int(bps[s])
			} else {
				bpsv = int(bps[0])
			}
		}
		if s >= len(planeData) {
			return 0
		}
		pd := planeData[s]
		if bpsv == 8 {
			idx := y*w + x
			if idx < len(pd) {
				return uint32(pd[idx])
			}
		} else if bpsv == 16 {
			idx := y*w + x
			if 2*idx+1 < len(pd) {
				return uint32(binary.BigEndian.Uint16(pd[2*idx:]))
			}
		}
		return 0
	}
	scaleVal := func(v uint32, bits int) uint8 {
		if bits == 8 {
			return uint8(v)
		}
		if bits == 16 {
			return uint8(v >> 8)
		}
		if bits == 0 || bits == 1 {
			if v != 0 {
				return 255
			}
			return 0
		}
		maxv := float64((1 << bits) - 1)
		if maxv == 0 {
			return uint8(v)
		}
		return uint8(float64(v) / maxv * 255)
	}

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			var vals []uint8
			for s := 0; s < samplesPerPixel; s++ {
				var v uint32
				var bits int
				if planar == 2 {
					bits = int(bps[0])
					if s < len(bps) {
						bits = int(bps[s])
					}
					v = getSamplePlanar(x, y, s)
				} else {
					v, bits = getSampleChunky(x, y, s)
				}
				vals = append(vals, scaleVal(v, bits))
			}
			var c color.RGBA
			switch photometric {
			case 2: // RGB
				r := uint8(0)
				g := uint8(0)
				b := uint8(0)
				if len(vals) > 0 {
					r = vals[0]
				}
				if len(vals) > 1 {
					g = vals[1]
				}
				if len(vals) > 2 {
					b = vals[2]
				}
				a := uint8(255)
				if len(vals) > 3 {
					// Extra sample treated as alpha (unassociated? keep).
					a = vals[3]
					img.Set(x, y, color.NRGBA{r, g, b, a})
					continue
				}
				c = color.RGBA{r, g, b, a}
			case 3: // palette
				idx := 0
				if len(vals) > 0 {
					// vals is scaled; for 8-bit indexes scaling is identity
					idx = int(vals[0])
					if bitsPerSample0 < 8 && bitsPerSample0 > 0 {
						// recover raw index
						vv, _ := getSampleChunky(x, y, 0)
						idx = int(vv)
					}
				}
				if idx < len(palette) {
					c = palette[idx]
				} else {
					c = color.RGBA{vals[0], vals[0], vals[0], 255}
				}
			case 0: // white is zero
				if len(vals) > 0 {
					gv := 255 - vals[0]
					c = color.RGBA{gv, gv, gv, 255}
				}
			default: // 1 black is zero, others as gray
				if len(vals) > 0 {
					if samplesPerPixel >= 3 {
						c = color.RGBA{vals[0], vals[1], vals[2], 255}
					} else {
						c = color.RGBA{vals[0], vals[0], vals[0], 255}
					}
				}
			}
			img.Set(x, y, c)
		}
	}
	return img, nil
}

