			return nil, errWebPInvalid
		}
	}
	_ = seenX
	return nil, errWebPInvalid
}

func decodeVP8Stub(p []byte) (image.Image, error) {
	if len(p) < 3 {
		return nil, io.ErrUnexpectedEOF
	}
	// Frame tag: bit0 type, bits1-3 version, bit4 show_frame, bits5+ part0 len.
	tag := uint32(p[0]) | uint32(p[1])<<8 | uint32(p[2])<<16
	frameType := tag & 1
	if frameType == 0 {
		// Key frame: expect start code 9d 01 2a after tag.
		if len(p) < 6 {
			return nil, io.ErrUnexpectedEOF
		}
		if !(p[3] == 0x9d && p[4] == 0x01 && p[5] == 0x2a) {
			return nil, errVP8Invalid
		}
		if len(p) < 10 {
			return nil, io.ErrUnexpectedEOF
		}
		// A valid keyframe header is present, but a full VP8 decoder is
		// outside this implementation's scope.
		return nil, errVP8Invalid
	}
	if len(p) < 10 {
		return nil, io.ErrUnexpectedEOF
	}
	return nil, errVP8Invalid
}

func decodeVP8LStub(p []byte) (image.Image, error) {
	if len(p) == 0 {
		return nil, io.ErrUnexpectedEOF
	}
	if p[0] != 0x2f {
		return nil, errVP8LHeader
	}
	if len(p) < 5 {
		return nil, io.ErrUnexpectedEOF
	}
	// Validate version bits (must be 0): bits after signature(8)+w(14)+h(14)+alpha(1).
	bits := uint64(0)
	for i := 0; i < 8 && i < len(p); i++ {
		bits |= uint64(p[i]) << (8 * i)
	}
	version := (bits >> (8 + 14 + 14 + 1)) & 7
	if version != 0 {
		return nil, errVP8LHeader
	}
	// A complete lossless decoder is not implemented; for most arbitrary
	// data this mirrors the reference Huffman failure.
	return nil, errVP8LHuffman
}
