func testDitherStrategy() string {
	// Temporary development hook; removed before final.
	if v := os.Getenv("PIXTERM_DITHER_TEST"); v != "" {
		return v
	}
	return ""
}

func newScaledDitherTest(img image.Image, src *image.NRGBA, cols, rows int, matte color.RGBA, scaleMode, ditherMode int, noBG bool, mode string) (*ansImage, error) {
	matteRGB := rgb{matte.R, matte.G, matte.B}
	// For fit mode keep the production quarter-fit behaviour in all strategies.
	if scaleMode == 2 {
		iw := src.Bounds().Dx()
		ih := src.Bounds().Dy()
		qw, qh := iw/4, ih/4
		if qw < 2 || qh < 4 {
			return nil, errANSImageSize
		}
		qsrc := resizeNRGBA(src, qw, qh)
		resized, err := scaledPixelImage(qsrc, cols, rows, scaleMode, 2)
		if err != nil {
			return nil, err
		}
		return ansFromDitherResized(resized, cols, rows, scaleMode, matte, matteRGB, ditherMode, noBG), nil
	}

	var pixImg *image.NRGBA
	var outRows int
	switch mode {
	case "pair":
		r, err := scaledPixelImage(src, cols, rows, scaleMode, 2)
		if err != nil {
			return nil, err
		}
		return ansFromDitherPaired(r, cols, rows, matte, matteRGB, ditherMode, noBG, "avg"), nil
	case "upper", "lower":
		r, err := scaledPixelImage(src, cols, rows, scaleMode, 2)
		if err != nil {
			return nil, err
		}
		return ansFromDitherPaired(r, cols, rows, matte, matteRGB, ditherMode, noBG, mode), nil
	case "directLanczos", "directBox", "directLinear", "directCatmull", "directMitchell", "directBSpline":
		// Resize source pixels directly to (cols, rows+1) with alternative kernel.
		// We reuse resizeKernelImage implemented in dither_test.go.
		r := resizeWithKernel(src, cols, rows+1, mode)
		pixImg = r
		outRows = rows
	case "directLanczosTr":
		r, err := scaledPixelImageDirect(src, cols, rows, scaleMode)
		if err != nil {
			return nil, err
		}
		pixImg = r
		outRows = rows
	default:
		r, err := scaledPixelImage(src, cols, rows, scaleMode, 2)
		if err != nil {
			return nil, err
		}
		return ansFromDitherPaired(r, cols, rows, matte, matteRGB, ditherMode, noBG, "avg"), nil
	}
	if pixImg == nil {
		return nil, errANSImageSize
	}
	ans := &ansImage{w: cols, h: outRows, dither: true, noBG: noBG, matte: matteRGB}
	for y := 0; y < outRows; y++ {
		for x := 0; x < cols; x++ {
			c := blendWithMatte(pixImg.NRGBAAt(x, y), matte)
			fg := rgb{c[0], c[1], c[2]}
			ans.pix = append(ans.pix, ansiPixel{bg: matteRGB, fg: fg, char: ditherCharFor(fg, ditherMode)})
		}
	}
	return ans, nil
}

func scaledPixelImageDirect(src *image.NRGBA, cols, rows, scaleMode int) (*image.NRGBA, error) {
	// Direct resize/fill/fit to (cols, rows) pixels using Lanczos imaging-style.
	boxW, boxH := cols, rows
	iw, ih := src.Bounds().Dx(), src.Bounds().Dy()
	switch scaleMode {
	case 0:
		return resizeNRGBA(src, boxW, boxH), nil
	case 1:
		var sw, sh int
		if boxW*ih >= boxH*iw {
			sw = boxW
			sh = (ih*boxW + iw/2) / iw
		} else {
			sh = boxH
			sw = (iw*boxH + ih/2) / ih
		}
		return cropCenter(resizeNRGBA(src, sw, sh), boxW, boxH), nil
	case 2:
		var sw, sh int
		if iw <= boxW && ih <= boxH {
			sw, sh = iw, ih
		} else if iw*boxH > ih*boxW {
			sw = boxW
			sh = boxW * ih / iw
		} else {
			sh = boxH
			sw = boxH * iw / ih
		}
		if sw < 2 || sh < 2 {
			return nil, errANSImageSize
		}
		return resizeNRGBA(src, sw, sh), nil
	}
	return nil, errANSImageSize
}

func ansFromDitherPaired(resized *image.NRGBA, cols, rows int, matte color.RGBA, matteRGB rgb, ditherMode int, noBG bool, pick string) *ansImage {
	sw := resized.Bounds().Dx()
	sh := resized.Bounds().Dy()
	pairs := sh / 2
	outRows := rows
	if outRows > pairs {
		outRows = pairs
	}
	ans := &ansImage{w: sw, h: outRows, dither: true, noBG: noBG, matte: matteRGB}
	for y := 0; y < outRows; y++ {
		for x := 0; x < sw; x++ {
			up := blendWithMatte(resized.NRGBAAt(x, y*2), matte)
			lo := blendWithMatte(resized.NRGBAAt(x, y*2+1), matte)
			var fg rgb
			switch pick {
			case "upper":
				fg = rgb{up[0], up[1], up[2]}
			case "lower":
				fg = rgb{lo[0], lo[1], lo[2]}
			default:
				fg = rgb{uint8((int(up[0]) + int(lo[0])) / 2), uint8((int(up[1]) + int(lo[1])) / 2), uint8((int(up[2]) + int(lo[2])) / 2)}
			}
			ans.pix = append(ans.pix, ansiPixel{bg: matteRGB, fg: fg, char: ditherCharFor(fg, ditherMode)})
		}
	}
	return ans
}
