package main

import (
	"image"
	"image/color"
	"math"
	"os"
)

// Temporary alternative-kernel resizer for strategy evaluation.
type kernelDef struct {
	support float64
	fn      func(float64) float64
}

func kernelFor(mode string) kernelDef {
	switch mode {
	case "directBox":
		return kernelDef{1, func(x float64) float64 {
			if x < 0 {
				x = -x
			}
			if x < 0.5 {
				return 1
			}
			return 0
		}}
	case "directLinear":
		return kernelDef{1, func(x float64) float64 {
			if x < 0 {
				x = -x
			}
			if x < 1 {
				return 1 - x
			}
			return 0
		}}
	case "directCatmull":
		return kernelDef{2, func(x float64) float64 {
			if x < 0 {
				x = -x
			}
			if x < 1 {
				return 1.5*x*x*x - 2.5*x*x + 1
			}
			if x < 2 {
				return -0.5*x*x*x + 2.5*x*x - 4*x + 2
			}
			return 0
		}}
	case "directMitchell":
		return kernelDef{2, func(x float64) float64 {
			if x < 0 {
				x = -x
			}
			B, C := 1.0/3, 1.0/3
			if x < 1 {
				return ((12-9*B-6*C)*x*x*x + (-18+12*B+6*C)*x*x + (6 - 2*B)) / 6
			}
			if x < 2 {
				return ((-B-6*C)*x*x*x + (6*B+30*C)*x*x + (-12*B-48*C)*x + (8*B + 24*C)) / 6
			}
			return 0
		}}
	case "directBSpline":
		return kernelDef{2, func(x float64) float64 {
			if x < 0 {
				x = -x
			}
			if x < 1 {
				return (4 - 6*x*x + 3*x*x*x) / 6
			}
			if x < 2 {
				d := 2 - x
				return d * d * d / 6
			}
			return 0
		}}
	default: // lanczos
		return kernelDef{3, lanczos3}
	}
}

func resizeWithKernel(src *image.NRGBA, dstW, dstH int, mode string) *image.NRGBA {
	// Note: direct* modes other than Lanczos use kernel not widened on downscale
	// unless mode is Lanczos (which reuses the production resizer through a
	// wrapper below). To keep evaluation simple, Lanczos uses production.
	if mode == "directLanczos" {
		// production resizer is Lanczos with widening; reuse by scaling via it:
		return resizeNRGBA(src, dstW, dstH)
	}
	kd := kernelFor(mode)
	srcW, srcH := src.Bounds().Dx(), src.Bounds().Dy()
	type cw struct {
		idx int
		w   float64
	}
	makeW := func(N, M int) [][]cw {
		scale := float64(N) / float64(M)
		out := make([][]cw, M)
		for i := 0; i < M; i++ {
			center := (float64(i)+0.5)*scale - 0.5
			supp := kd.support // not widened
			var lst []cw
			sum := 0.0
			for j := int(math.Floor(center - supp)); j <= int(math.Ceil(center+supp)); j++ {
				if j < 0 || j >= N {
					continue
				}
				w := kd.fn((float64(j) - center))
				lst = append(lst, cw{j, w})
				sum += w
			}
			if sum != 0 {
				for t := range lst {
					lst[t].w /= sum
				}
			}
			out[i] = lst
		}
		return out
	}
	wx := makeW(srcW, dstW)
	wy := makeW(srcH, dstH)
	tmp := image.NewNRGBA(image.Rect(0, 0, dstW, srcH))
	for y := 0; y < srcH; y++ {
		for x := 0; x < dstW; x++ {
			var pr, pg, pb, a float64
			for _, c := range wx[x] {
				p := src.NRGBAAt(c.idx, y)
				fa := float64(p.A)
				pr += c.w * float64(p.R) * fa / 255
				pg += c.w * float64(p.G) * fa / 255
				pb += c.w * float64(p.B) * fa / 255
				a += c.w * fa
			}
			tmp.SetNRGBA(x, y, storePremult(pr, pg, pb, a))
		}
	}
	out := image.NewNRGBA(image.Rect(0, 0, dstW, dstH))
	for y := 0; y < dstH; y++ {
		for x := 0; x < dstW; x++ {
			var pr, pg, pb, a float64
			for _, c := range wy[y] {
				p := tmp.NRGBAAt(x, c.idx)
				fa := float64(p.A)
				pr += c.w * float64(p.R) * fa / 255
				pg += c.w * float64(p.G) * fa / 255
				pb += c.w * float64(p.B) * fa / 255
				a += c.w * fa
			}
			out.SetNRGBA(x, y, storePremult(pr, pg, pb, a))
		}
	}
	return out
}

var _ = os.Getenv
var _ color.RGBA
