func resizeWideTest(src *image.NRGBA, dstW, dstH int, mode string) *image.NRGBA {
	var kd kernelDef
	switch mode {
	case "wideBox":
		kd = kernelDef{0.5, func(x float64) float64 { if x < 0 { x = -x }; if x < 0.5 { return 1 }; return 0 }}
	case "wideLinear":
		kd = kernelDef{1, func(x float64) float64 { if x < 0 { x = -x }; if x < 1 { return 1 - x }; return 0 }}
	case "wideCatmull":
		kd = kernelDef{2, func(x float64) float64 { if x < 0 { x = -x }; if x < 1 { return 1.5*x*x*x - 2.5*x*x + 1 }; if x < 2 { return -0.5*x*x*x + 2.5*x*x - 4*x + 2 }; return 0 }}
	case "wideMitchell":
		kd = kernelDef{2, func(x float64) float64 { if x < 0 { x = -x }; B, C := 1.0/3.0, 1.0/3.0; if x < 1 { return ((12-9*B-6*C)*x*x*x + (-18+12*B+6*C)*x*x + (6-2*B))/6 }; if x < 2 { return ((-B-6*C)*x*x*x + (6*B+30*C)*x*x + (-12*B-48*C)*x + (8*B+24*C))/6 }; return 0 }}
	case "wideBSpline":
		kd = kernelDef{2, func(x float64) float64 { if x < 0 { x = -x }; if x < 1 { return (4 - 6*x*x + 3*x*x*x)/6 }; if x < 2 { d := 2-x; return d*d*d/6 }; return 0 }}
	case "wideHermite":
		kd = kernelDef{1, func(x float64) float64 { if x < 0 { x = -x }; if x < 1 { return (2*x-3)*x*x + 1 }; return 0 }}
	case "wideLanczos2":
		kd = kernelDef{2, func(x float64) float64 { if x == 0 { return 1 }; if x < -2 || x > 2 { return 0 }; return sinc(x)*sinc(x/2) }}
	}
	return resizeWithKernelDefWide(src, dstW, dstH, kd)
}
