func resizeBoxVH(src *image.NRGBA, dstW, dstH int) *image.NRGBA {
	kd := kernelDef{0.5, func(x float64) float64 {
		if x < 0 {
			x = -x
		}
		if x < 0.5 {
			return 1
		}
		return 0
	}}
	srcW, srcH := src.Bounds().Dx(), src.Bounds().Dy()
	type cw struct {
		idx int
		w   float64
	}
	makeW := func(N, M int) [][]cw {
		scale := float64(N) / float64(M)
		factor := math.Max(1, scale)
		supp := kd.support * factor
		out := make([][]cw, M)
		for i := 0; i < M; i++ {
			center := (float64(i)+0.5)*scale - 0.5
			var lst []cw
			sum := 0.0
			for j := int(math.Floor(center - supp)); j <= int(math.Ceil(center+supp)); j++ {
				if j < 0 || j >= N {
					continue
				}
				w := kd.fn((float64(j) - center) / factor)
				lst = append(lst, cw{j, w})
				sum += w
			}
			if sum != 0 {
				for t := range lst {
					lst[t].w /= sum
				}
			}
			out[i] = lst
		}
		return out
	}
	wx := makeW(srcW, dstW)
	wy := makeW(srcH, dstH)
	// Vertical first.
	tmp := image.NewNRGBA(image.Rect(0, 0, srcW, dstH))
	for y := 0; y < dstH; y++ {
		for x := 0; x < srcW; x++ {
			var pr, pg, pb, a float64
			for _, c := range wy[y] {
				p := src.NRGBAAt(x, c.idx)
				fa := float64(p.A)
				pr += c.w * float64(p.R) * fa / 255
				pg += c.w * float64(p.G) * fa / 255
				pb += c.w * float64(p.B) * fa / 255
				a += c.w * fa
			}
			tmp.SetNRGBA(x, y, storePremult(pr, pg, pb, a))
		}
	}
	out := image.NewNRGBA(image.Rect(0, 0, dstW, dstH))
	for y := 0; y < dstH; y++ {
		for x := 0; x < dstW; x++ {
			var pr, pg, pb, a float64
			for _, c := range wx[x] {
				p := tmp.NRGBAAt(c.idx, y)
				fa := float64(p.A)
				pr += c.w * float64(p.R) * fa / 255
				pg += c.w * float64(p.G) * fa / 255
				pb += c.w * float64(p.B) * fa / 255
				a += c.w * fa
			}
			out.SetNRGBA(x, y, storePremult(pr, pg, pb, a))
		}
	}
	return out
}
