		cropCeil = true
	} else if variant == "croppre" {
		// Crop source to box aspect first, then resize to box.
		// crop width/height by integer truncation centred.
		var cw, ch int
		if iw*boxH > ih*boxW {
			ch = ih
			cw = ih * boxW / boxH
		} else {
			cw = iw
			ch = iw * boxH / boxW
		}
		ox := (iw - cw) / 2
		oy := (ih - ch) / 2
		cropped := image.NewNRGBA(image.Rect(0, 0, cw, ch))
