	calc := func(num, den int) int {
		switch roundMode {
		case "ceil":
			return (num + den - 1) / den
		case "floor":
			return num / den
		default:
			return (num + den/2) / den
		}
	}
	if boxW*ih >= boxH*iw {
		sw = boxW
		sh = calc(ih*boxW, iw)
	} else {
		sh = boxH
		sw = calc(iw*boxH, ih)
	}
	resized := resizeNRGBA(src, sw, sh)
	if cropCeil {
		out := image.NewNRGBA(image.Rect(0, 0, boxW, boxH))
		ox := (sw - boxW + 1) / 2
		oy := (sh - boxH + 1) / 2
		drawimg.Draw(out, out.Bounds(), resized, image.Pt(ox, oy), drawimg.Src)
		return out, nil
	}
	return cropCenter(resized, boxW, boxH), nil
}
'''
