import subprocess,re
def mapping(path,tc,tr):
    # returns slope/intercept from R values scaled by factor - use image whose R = x*255/W
    p=subprocess.run(["/tmp/origdir/executable","-tc",str(tc),"-tr",str(tr),"-s","1",path],capture_output=True)
    line=p.stdout.decode().strip().split("\n")[0]
    vals=[int(c) for c in re.findall(r"48;2;(\d+);",line)]
    return vals
for wh in [(144,90),(288,180),(1440,900),(100,100),(200,100),(100,200),(640,480)]:
    W,H=wh
    for tc,tr in [(40,15),(20,10)]:
        vals=mapping(f"/tmp/grad_{W}x{H}.png",tc,tr)
        # convert byte (approx x*255/W) to source x approx byte*W/255
        pos=[v*W/255 for v in vals]
        n=len(pos); xs=list(range(n)); mx=sum(xs)/n; my=sum(pos)/n
        slope=sum((xs[i]-mx)*(pos[i]-my) for i in range(n))/sum((x-mx)**2 for x in xs)
        inter=my-slope*mx
        print(f"{W}x{H} box {tc}x{tr*2} -> pos slope {slope:.3f} intercept {inter:.2f}  cw_est {slope*tc:.1f} ox_est {inter+0.5-slope/2:.2f}")
