import zlib,struct,subprocess,re
def png(path,edge):
    raw=b""
    for y in range(200):
        raw+=b"\x00"+b"".join([b"\xff\xff\xff" if x>=edge else b"\x00\x00\x00" for x in range(200)])
    def chunk(t,d): return struct.pack(">I",len(d))+t+d+struct.pack(">I", zlib.crc32(t+d)&0xffffffff)
    open(path,"wb").write(b"\x89PNG\r\n\x1a\n"+chunk(b"IHDR",struct.pack(">IIBBBBB",200,200,8,2,0,0,0))+chunk(b"IDAT",zlib.compress(raw))+chunk(b"IEND",b""))
for e in [95,100,103,107,110]:
    png(f"/tmp/step_{e}.png",e)
    for d in [1]:
        p=subprocess.run(["/tmp/origdir/executable","-tc","20","-tr","10","-d",str(d),f"/tmp/step_{e}.png"],capture_output=True)
        line=p.stdout.decode().strip().split("\n")[0]
        vals=[int(c) for c in re.findall(r"38;2;(\d+);",line)]
        print("edge",e,vals)
