// scaledPixelImageHybrid is like scaledPixelImage for resize/fill but uses
// the hybrid (area/Lanczos) resizer instead of the plain Lanczos resizer.
// It returns nil if the computed size is invalid (caller then falls back).
func scaledPixelImageHybrid(src *image.NRGBA, cols, rows, scaleMode, k int) *image.NRGBA {
	iw := src.Bounds().Dx()
	ih := src.Bounds().Dy()
	boxW := cols
	boxH := (rows + 1) * k
	if cols < 2 || boxH < 2 {
		return nil
	}
	switch scaleMode {
	case 0:
		return resizeHybrid(src, boxW, boxH)
	case 1:
		var sw, sh int
		if boxW*ih >= boxH*iw {
			sw = boxW
			sh = (ih*boxW + iw/2) / iw
		} else {
			sh = boxH
			sw = (iw*boxH + ih/2) / ih
		}
		if sw < 2 || sh < 2 {
			return nil
		}
		resized := resizeHybrid(src, sw, sh)
		return cropCenter(resized, boxW, boxH)
	}
	return nil
}
GO
